INSERT INTO `diary_comments` VALUES (1,9,'DIARY_PROFILE',NULL,'\nХочу к лету сбросить 4–5 кг, но без жёстких ограничений. Действия на сейчас - начать нормально завтракать и меньше есть на ночь.\n',9,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(2,41,'DIARY_PROFILE',NULL,'\nПоследние месяцы постоянно хочется сладкого после ужина. Наверное, не хватает сна или просто нервы. Попробую заменить на йогурт или фрукты.\n',41,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(3,63,'DIARY_PROFILE',NULL,'\nЦель на ближайший месяц — добавить больше белка и овощей. Мясо ем нормально, а вот с овощами пока слабовато.\n',63,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(4,79,'DIARY_PROFILE',NULL,'\nЧасто вечером набрасываюсь на всё подряд в рабочие дни. Хочется как-то наладить нормальный режим питания.\n',79,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(5,57,'DIARY_PROFILE',NULL,'\nВес стоит на месте уже две недели, хотя вроде ем не вредную еду. Надеюсь тут наладить свой рацион.\n',57,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(6,32,'DIARY_PROFILE',NULL,'\nПросто хочу научиться есть спокойно, без чувства вины. Устала от вечных качелей «сегодня можно всё — завтра ничего».\n',32,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(7,8,'DIARY_PROFILE',NULL,'\nПосле каждых выходных очень тяжело и физически и эмоционально и при этом не понимаю почему. Надесь в этом приложении настроить рацион так чтобы чувствовать себя намного лучше.\n',8,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(8,24,'DIARY_PROFILE',NULL,'\nПока просто наблюдаю. Не ставлю жёстких целей, хочу понять, как работать с питанием и имеет ли смысл от такого приложения.\n',24,'2026-08-06 22:23:25','2026-08-26 18:24:09',NULL),(9,1,'DIARY_PROFILE',NULL,'Пациентка склонна к эмоциональному перееданию во второй половине дня. Основной фокус — стабилизация режима питания и работа с чувством голода/сытости. Рекомендовано вести более подробные заметки о состоянии до и после еды.',7,'2026-08-06 23:04:26','2026-08-26 18:23:14',NULL),(10,20,'DIARY_PROFILE',NULL,'Ребёнок ест избирательно, много простых углеводов, мало белка и овощей. Важно не давить, а постепенно расширять рацион через знакомые продукты. Родителям рекомендовано убрать из свободного доступа сладкие перекусы.',87,'2026-08-06 23:04:26','2026-08-26 18:23:14',NULL),(11,3,'DIARY_PROFILE',NULL,'Молодой пациент часто пропускает приёмы пищи из-за учёбы/работы, после чего случаются эпизоды переедания. Необходимо выстроить минимальный стабильный каркас: завтрак + обед + ужин без длительных перерывов.',14,'2026-08-06 23:04:26','2026-08-26 18:23:14',NULL),(12,32,'DIARY_PROFILE',NULL,'Отмечается выраженный страх «запрещённых» продуктов и циклы ограничений с последующими срывами. Работаем над снижением тревоги вокруг еды и возвращением более гибкого подхода к рациону.',97,'2026-08-06 23:04:26','2026-08-26 18:23:14',NULL),(13,60,'DIARY_PROFILE',NULL,'Пациентка хорошо держит структуру питания, но склонена сильно снижать калорийность. Есть признаки недостатка энергии. Рекомендовано аккуратно повысить калораж и добавить больше разнообразного белка.',31,'2026-08-06 23:04:26','2026-08-26 18:23:14',NULL),(14,53,'DIARY_PROFILE',NULL,'Наблюдается нестабильный режим: в будни питание относительно контролируемое, в выходные — заметные переборы. Основная задача — сгладить разницу между буднями и выходными без жёстких запретов.',44,'2026-08-06 23:04:26','2026-08-26 18:23:14',NULL),(15,23,'DIARY_PROFILE',NULL,'Пациент достаточно осознанный, но склонен к самокритике после небольших отхождений от плана. Важно сместить акцент с «идеального соблюдения» на устойчивость привычек и общее самочувствие.',89,'2026-08-06 23:04:26','2026-08-26 18:23:14',NULL),(70,9,'MEAL',90001,'Начинаю как планировала — с нормального завтрака.',9,'2026-05-12 09:30:00','2026-08-26 18:24:09',NULL),(71,9,'MEAL',90003,'Не удержалась, съела целую плитку шоколада перед сном. Очень стыдно.',9,'2026-05-12 22:05:00','2026-08-26 18:24:09',NULL),(72,9,'MEAL',90006,'Забыла поесть, завалили работой.',9,'2026-05-14 14:00:00','2026-08-26 18:24:09',NULL),(73,9,'WEIGHT_LOG',9002,'После каждых выходных очень тяжело и физически и эмоционально.',9,'2026-05-18 07:35:00','2026-08-26 18:24:09',NULL),(75,9,'SLEEP_LOG',9003,'Мало спала, весь день тянет на сладкое.',9,'2026-05-28 07:00:00','2026-08-26 18:24:09',NULL),(77,9,'WEIGHT_LOG',9005,'Вес 68.8. Медленно, но прогресс есть. Начинаю июнь без срывов.',9,'2026-06-01 07:20:00','2026-08-26 18:24:09',NULL),(78,9,'MEAL',90018,'Тяжелый день, отчеты. Наелась сладкого на ночь, опять...',9,'2026-06-03 22:50:00','2026-08-26 18:24:09',NULL),(79,9,'MEAL',90019,'Не заслужила обед после вчерашнего.',9,'2026-06-04 13:05:00','2026-08-26 18:24:09',NULL),(81,9,'SLEEP_LOG',9004,'Ужасно не выспалась. Вечером очень хотелось шоколада, но вспомнила совет и съела йогурт. Горжусь собой.',9,'2026-06-10 21:50:00','2026-08-26 18:24:09',NULL),(82,9,'MEAL',90022,'Обед сегодня очень сытный, надеюсь, вечером будет легче.',9,'2026-06-17 14:05:00','2026-08-26 18:24:09',NULL),(83,9,'WEIGHT_LOG',9008,'Опять 69.4. Каждые выходные — шаг назад. Сегодня только завтрак и легкий ужин.',9,'2026-06-22 07:35:00','2026-08-26 18:24:09',NULL),(84,9,'SLEEP_LOG',9005,'Всего 4.5 часа сна. Голова раскалывается, тянет на мучное.',9,'2026-06-24 07:00:00','2026-08-26 18:24:09',NULL),(85,9,'MEAL',90029,'Не выдержала, усталость после недели взяла своё.',9,'2026-06-26 22:50:00','2026-08-26 18:24:09',NULL),(87,9,'MEAL',90030,'Сделала обед поплотнее, как советовала диетолог.',9,'2026-07-01 14:05:00','2026-08-26 18:24:09',NULL),(88,9,'MEAL',90031,'Вместо конфет взяла йогурт. Сработало!',9,'2026-07-03 21:50:00','2026-08-26 18:24:09',NULL),(89,9,'WEIGHT_LOG',9011,'После выходных опять тяжело. Начинаю неделю строго.',9,'2026-07-13 07:20:00','2026-08-26 18:24:09',NULL),(90,9,'SLEEP_LOG',9006,'Мало спала, весь день вялость и хочется печенья.',9,'2026-07-15 07:00:00','2026-08-26 18:24:09',NULL),(91,9,'MEAL',90039,'Конец недели, сорвалась на сладкое перед телевизором.',9,'2026-07-17 22:50:00','2026-08-26 18:24:09',NULL),(94,9,'MEAL',90042,'Хотелось конфет, но выбрала йогурт. Маленькая победа.',9,'2026-07-24 21:50:00','2026-08-26 18:24:09',NULL),(95,9,'WEIGHT_LOG',9012,'Наконец-то ниже 69! Стабильность в будни помогает.',9,'2026-07-27 07:20:00','2026-08-26 18:24:09',NULL),(96,9,'MEAL',90046,'Конец недели, очень устала и сорвалась на сладкое.',9,'2026-07-31 22:35:00','2026-08-26 18:24:09',NULL),(97,9,'WEIGHT_LOG',9013,'Опять +300г после выходных. Решила сегодня почти не обедать.',9,'2026-08-03 07:20:00','2026-08-26 18:24:09',NULL),(99,9,'SLEEP_LOG',9007,'Всего 4.5 часа сна. Тянет на печенье весь день.',9,'2026-08-05 07:00:00','2026-08-26 18:24:09',NULL),(100,9,'MEAL',90051,'Вспомнила совет диетолога и заменила печенье йогуртом. Получилось!',9,'2026-08-06 21:50:00','2026-08-26 18:24:09',NULL);
