INSERT INTO `recipes` VALUES (1,'RECIPE_00000001','Сметанное песочное тесто','Главная особенность этого теста — большое содержание жира (масло и сметана) и использование только желтков, что делает готовую выпечку особенно нежной, рассыпчатой и песочной','Для теста просеять в миску муку с сахарной пудрой, разрыхлителем и солью. Перемешать до однородности; \n Холодное сливочное масло натереть на мелкой тёрке прямо в мучную смесь;\n Желтки отделить от белков. Желтки вместе со сметаной добавить в миску;\n Замесить гладкое эластичное тесто. Получилось примерно 800 г.','RECIPE_00000001.jpg',NULL,1,0,NULL,'2026-08-05 18:30:24',NULL,NULL),(2,'RECIPE_00000002','Шоколадная масляная глазурь','«Домашний» ганаш на основе какао, масла и молока. Его чаще называют масляной шоколадной глазурью.','Масло должно быть комнатной температуры, а молоко — теплым (но не горячим!). Если молоко будет слишком горячим, масло расслоится, и глазурь станет зернистой. Если все сделать правильно, она получится гладкой, блестящей и очень вкусной;\n Для глазури какао, сахарную пудру и сливочное масло соединить в кастрюле;\n Влить молоко. Перемешать;\n Постоянно помешивая, прогреть на небольшом огне до получения однородной, гладкой глазури и её лёгкого загустения;','RECIPE_00000002.jpg',NULL,1,0,NULL,'2026-08-06 04:35:54',NULL,NULL),(3,'RECIPE_00000003','Макош пите (Маковый пирог)','Макош пите (венг. Mákos pite) – традиционный венгерский маковый пирог. \n Между двумя коржами песочного теста находится толстый слой воздушной \n маковой начинки. Сверху пирог декорируется сахарной пудрой или \n какао-глазурью. Макош пите получается нежным, в меру сладким и очень \n маковым.','Мак измельчить в кофемолке или блендере;','RECIPE_00000003.jpg',NULL,1,0,NULL,'2026-08-06 05:56:00',NULL,NULL),(4,'RECIPE_00000004','Дынное мороженое со сгущёнкой','Нежный домашний десерт с насыщенным ароматом спелой дыни и приятной сливочной текстурой. Благодаря сгущённому молоку мороженое получается особенно кремовым и очень нежным по вкусу.','Подготавливаем необходимые продукты;','RECIPE_00000004.jpg',NULL,1,0,NULL,'2026-08-06 09:37:54',NULL,NULL);
/*!40000 ALTER TABLE `recipes` ENABLE KEYS */;
UNLOCK TABLES;

